 ball('#b4c9cb',0,1.8,0,3.6,2.2,1.5,blanc);ball('#f0eee0',0,2.65,.1,2.5,1.35,1.2,blanc);ball('#d8e4dc',-2,1.9,.1,1.5,1.1,.8,blanc);
 for(const x of[-1.3,-.4,.7])beam('#a3bac2',[x,1.1,1.1],[x+.4,3.25,1.1],.07,blanc);
